<?php
require_once __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/service_management.php';require_admin();
$service=find_service(input_text($_GET,'id'),true);if(!$service)render_error(404,'That service is not here.','The record may already have been removed.');
$linked=(int)query('SELECT COUNT(*) FROM appointment_requests WHERE service_id=?',[$service['id']])->fetchColumn();$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
    require_csrf();
    if(input_text($_POST,'confirm_delete')!=='1'){$error='Please check the confirmation box to intentionally delete this service.';http_response_code(422);}
    else {try{delete_service((int)$service['id']);flash('Deleted '.$service['name'].'.');redirect('admin/services.php');}catch(DomainException $exception){$error=$exception->getMessage();http_response_code(409);}}
}
$pageTitle='Delete service | Wellnest Workspace';$adminSection='services';$adminPageLabel='Delete service';require __DIR__.'/../components/admin_header.php';
?>
<a class="admin-back" href="<?=e(base_url('admin/services.php'))?>"><?=icon('arrow')?> Back to medical services</a><section class="delete-panel admin-panel"><span class="delete-icon"><?=icon('trash')?></span><span class="admin-eyebrow">A MOMENT TO DOUBLE-CHECK</span><h1>Delete this service?</h1><p>This permanently removes <strong><?=e($service['name'])?></strong> from the catalog. This action cannot be undone.</p><div class="delete-service-summary"><img src="<?=e(base_url('public/images/'.$service['image']))?>" alt="<?=e($service['alt'])?>" width="80" height="65"><div><strong><?=e($service['name'])?></strong><p><?=e($service['category'])?> · <?=money((int)$service['price'])?></p></div></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif; ?><?php if($linked): ?><div class="alert alert-warning"><strong>Existing requests need this record.</strong><br>This service has <?=$linked?> appointment <?=$linked===1?'request':'requests'?>. Set it to Draft instead; existing care history will be preserved.</div><a class="btn btn-primary" href="<?=e(base_url('admin/service_form.php?id='.$service['id']))?>">Edit publication status <?=icon('arrow')?></a><?php else: ?><form method="post"><?=csrf_field()?><div class="form-check mb-4"><input class="form-check-input" type="checkbox" name="confirm_delete" id="confirm-delete" value="1" required><label class="form-check-label" for="confirm-delete">I understand and want to permanently delete this service.</label></div><div class="delete-actions"><button type="submit" class="btn btn-danger"><?=icon('trash')?> Delete service</button><a class="btn btn-editor-cancel" href="<?=e(base_url('admin/services.php'))?>">Keep service</a></div></form><?php endif; ?></section>
